import signal
import sys
import time

from gpiozero import DigitalOutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

# BCM pin numbers for the digital outputs
OUTPUT_PINS = [2, 3, 4]

# Global list to track devices for cleanup
_devices = []


def _cleanup():
    """Close every device we opened, ignoring errors during teardown."""
    for dev in _devices:
        try:
            dev.close()
        except DeviceClosed:
            pass
        except Exception:
            pass
    _devices.clear()


def _handle_signal(signum, frame):
    """Handle SIGINT / SIGTERM by raising KeyboardInterrupt for graceful exit."""
    raise KeyboardInterrupt(f"Received signal {signum}")


def main():
    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # Initialize digital output devices
    try:
        for pin in OUTPUT_PINS:
            dev = DigitalOutputDevice(pin)
            _devices.append(dev)
    except GPIOZeroError as exc:
        print(f"Error: failed to initialize GPIO outputs: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(1)
    except Exception as exc:
        print(f"Unexpected error during initialization: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    try:
        while True:
            for dev in _devices:
                try:
                    dev.on()
                    print(f"GPIO {dev.pin.number} set HIGH")
                except DeviceClosed:
                    print(f"Error: device on GPIO {dev.pin.number} is closed", file=sys.stderr)
                except Exception as exc:
                    print(f"Error writing to GPIO {dev.pin.number}: {exc}", file=sys.stderr)
                time.sleep(60)
                try:
                    dev.off()
                    print(f"GPIO {dev.pin.number} set LOW")
                except DeviceClosed:
                    print(f"Error: device on GPIO {dev.pin.number} is closed", file=sys.stderr)
                except Exception as exc:
                    print(f"Error writing to GPIO {dev.pin.number}: {exc}", file=sys.stderr)
                time.sleep(60)
    except KeyboardInterrupt:
        print("\nInterrupt received, exiting...")
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

import time
import signal
import sys
import board
import busio
import adafruit_ads1x15.ads1115 as ADS
from adafruit_ads1x15.analog_in import AnalogIn

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    i2c = None
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        ads = ADS.ADS1115(i2c, address=0x48)
    except Exception as e:
        print(f"Error initializing ADS1115 at 0x48: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        ads.gain = 1
    except Exception as e:
        print(f"Error setting ADS1115 gain: {e}", file=sys.stderr)
        sys.exit(1)

    channel = AnalogIn(ads, ADS.P0)

    while _running:
        try:
            voltage = channel.voltage
        except Exception as e:
            print(f"Error reading ADS1115 channel 0: {e}", file=sys.stderr)
            break

        if voltage is None:
            print("Error: ADS1115 returned no data (device may be absent or unresponsive).", file=sys.stderr)
            break

        print(f"Voltage: {voltage:.4f} V")
        time.sleep(0.1)

    if i2c is not None:
        try:
            i2c.deinit()
        except Exception:
            pass
    sys.exit(0)

if __name__ == "__main__":
    main()

