import signal
import sys
import time

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError

PWM_PINS = [1, 2, 3, 4]
POLL_INTERVAL = 0.1

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = []
    try:
        for pin in PWM_PINS:
            try:
                dev = PWMOutputDevice(pin)
                devices.append(dev)
            except GPIOZeroError as exc:
                print(f"Error: failed to initialize PWM on GPIO {pin}: {exc}", file=sys.stderr)
                for d in devices:
                    d.close()
                sys.exit(1)

        while _running:
            values = []
            for dev in devices:
                try:
                    values.append(dev.value)
                except GPIOZeroError as exc:
                    print(f"Warning: failed to read PWM on GPIO {dev.pin}: {exc}", file=sys.stderr)
                    values.append(None)

            for idx, val in enumerate(values):
                if val is not None:
                    print(f"GPIO {PWM_PINS[idx]}: {val:.4f}")
                else:
                    print(f"GPIO {PWM_PINS[idx]}: read error")

            time.sleep(POLL_INTERVAL)

    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        for dev in devices:
            try:
                dev.close()
            except Exception:
                pass


if __name__ == "__main__":
    main()

