import serial
import time
import sys

SERIAL_PORT = '/dev/serial0'  # Raspberry Pi primary UART (BCM 14/15)
BAUD_RATE = 115200
READ_TIMEOUT = 1.0
INTERVAL = 1.0


def read_sensor_data(ser):
    """Read one line from the serial port and return it as a stripped string."""
    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        print(f"Serial read error: {exc}", file=sys.stderr)
        return None
    if not raw:
        return None
    return raw.decode('utf-8', errors='replace').strip()


def main():
    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            timeout=READ_TIMEOUT,
            write_timeout=READ_TIMEOUT,
        )
    except serial.SerialException as exc:
        print(f"Failed to open {SERIAL_PORT}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while True:
            data = read_sensor_data(ser)
            if data:
                print(f"Sensor Reading: {data}")
            else:
                print("No data received (timeout).", file=sys.stderr)
            time.sleep(INTERVAL)
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    finally:
        if ser.is_open:
            ser.close()
            print("Serial port closed.")


if __name__ == "__main__":
    main()

