import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

PIN = 17
CYCLES = 5
DELAY_SECONDS = 2.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        device = OutputDevice(PIN)
    except GPIOZeroError as exc:
        print(f"Failed to initialize GPIO {PIN}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        for cycle in range(1, CYCLES + 1):
            if not _running:
                print("Interrupted by signal; stopping early.", file=sys.stderr)
                break

            try:
                device.on()
                print(f"Cycle {cycle}/{CYCLES}: GPIO {PIN} -> HIGH")
            except GPIOZeroError as exc:
                print(f"Cycle {cycle}/{CYCLES}: failed to drive HIGH: {exc}", file=sys.stderr)
                break

            if cycle < CYCLES and _running:
                time.sleep(DELAY_SECONDS)

            if not _running:
                break

            try:
                device.off()
                print(f"Cycle {cycle}/{CYCLES}: GPIO {PIN} -> LOW")
            except GPIOZeroError as exc:
                print(f"Cycle {cycle}/{CYCLES}: failed to drive LOW: {exc}", file=sys.stderr)
                break

            if cycle < CYCLES and _running:
                time.sleep(DELAY_SECONDS)

    finally:
        try:
            device.close()
        except Exception:
            pass
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

