import serial
import time
import sys

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 115200
READ_TIMEOUT = 5
INTERVAL_SECONDS = 5


def read_sensor_data(ser):
    """Read one line from the serial port and return it stripped, or None."""
    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        print(f"Serial read error: {exc}", file=sys.stderr)
        return None
    if not raw:
        return None
    return raw.decode('utf-8', errors='replace').strip()


def process_sensor_data(data):
    """Validate the reading; return True if it is acceptable."""
    if not data:
        return False
    return True


def main():
    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            timeout=READ_TIMEOUT,
        )
    except serial.SerialException as exc:
        print(f"Failed to open serial port {SERIAL_PORT}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while True:
            data = read_sensor_data(ser)
            if data is None:
                print("No data received from device.", file=sys.stderr)
                break
            if process_sensor_data(data):
                print(f"Sensor Reading: {data}")
            else:
                print("Invalid data received.", file=sys.stderr)
                break
            time.sleep(INTERVAL_SECONDS)
    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    finally:
        if ser.is_open:
            ser.close()
            print("Serial port closed.")


if __name__ == "__main__":
