import signal
import sys

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 115200
READ_TIMEOUT = 1.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def is_valid_reading(reading):
    return isinstance(reading, str) and reading.strip() != ''

def process_reading(reading):
    print(f"Received: {reading}", flush=True)

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            timeout=READ_TIMEOUT,
            write_timeout=READ_TIMEOUT,
        )
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                raw = ser.readline()
            except serial.SerialException as e:
                print(f"Serial read error: {e}", file=sys.stderr)
                break

            if not raw:
                continue

            reading = raw.decode('utf-8', errors='replace').strip()
            if not is_valid_reading(reading):
                continue

            process_reading(reading)
    finally:
        try:
            ser.close()
        except Exception:
            pass

