import sys
import signal
import logging

from picamera2 import Picamera2

logging.basicConfig(level=logging.INFO, format="%(levelname)s: %(message)s")
log = logging.getLogger("camera")

_running = True

def _signal_handler(signum, frame):
    global _running
    log.info("Signal %s received, shutting down.", signum)
    _running = False

def capture_image(filename: str) -> int:
    try:
        picam2 = Picamera2()
    except Exception as exc:
        log.error("Failed to initialize camera: %s", exc)
        return 1

    try:
        picam2.start()
        log.info("Camera started.")
    except Exception as exc:
        log.error("Failed to start camera: %s", exc)
        return 1

    try:
        picam2.capture_file(filename)
        log.info("Image saved to %s", filename)
        return 0
    except Exception as exc:
        log.error("Failed to capture image: %s", exc)
        return 1
    finally:
        try:
            picam2.stop()
            log.info("Camera stopped.")
        except Exception as exc:
            log.warning("Error stopping camera: %s", exc)

def main() -> int:
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    filename = "image.jpg"
    if not _running:
        return 1

    return capture_image(filename)

if __name__ == "__main__":
    sys.exit(main())

