def measure_distance(sensor):
    """Return distance in meters, or None on failure."""
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            distance = sensor.distance
            if distance is None or distance < 0 or distance > MAX_DISTANCE_M:
                raise ValueError(f"Out-of-range reading: {distance}")
            return distance
        except Exception as exc:
            print(f"  [warn] attempt {attempt}/{MAX_RETRIES} failed: {exc}", file=sys.stderr)
            if attempt < MAX_RETRIES:
                time.sleep(RETRY_DELAY_S)
    return None


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        sensor = DistanceSensor(
            echo=ECHO_PIN,
            trigger=TRIGGER_PIN,
            max_distance=MAX_DISTANCE_M,
            threshold_distance=0.01,
        )
    except Exception as exc:
        print(f"Failed to initialize HC-SR04 on echo={ECHO_PIN}, trigger={TRIGGER_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        for cycle in range(1, CYCLES + 1):
            if not _running:
                print("\nInterrupted by signal; exiting cleanly.")
                break

            print(f"\n--- Cycle {cycle}/{CYCLES} ---")
            time.sleep(SETTLE_S)

            distance = measure_distance(sensor)
            if distance is None:
                print("  [error] Distance measurement failed after retries.")
            else:
                print(f"  Distance: {distance:.3f} meters")

            if cycle < CYCLES and _running:
                time.sleep(CYCLE_INTERVAL_S)

    finally:
        try:
            sensor.close()
        except Exception:
            pass
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

