import signal
import sys

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 115200
READ_TIMEOUT = 1.0
NUM_READINGS = 3
INTERVAL = 1.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            timeout=READ_TIMEOUT,
            write_timeout=READ_TIMEOUT,
        )
    except serial.SerialException as exc:
        print(f"Error opening serial port {SERIAL_PORT}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        for i in range(NUM_READINGS):
            if not _running:
                print("Interrupted by user.", file=sys.stderr)
                break

            try:
                raw = ser.readline()
            except serial.SerialException as exc:
                print(f"Read error on attempt {i + 1}: {exc}", file=sys.stderr)
                break

            if not raw:
                print(f"Attempt {i + 1}: no data received (timeout).", file=sys.stderr)
                continue

            try:
                data = raw.decode('utf-8', errors='replace').strip()
            except Exception as exc:
                print(f"Decode error on attempt {i + 1}: {exc}", file=sys.stderr)
                continue

            if data:
                print(f"Reading {i + 1}: {data}")
            else:
                print(f"Attempt {i + 1}: empty line received.")

            if i < NUM_READINGS - 1:
                time.sleep(INTERVAL)
    finally:
        try:
            ser.close()
        except Exception:
            pass

