import serial
import time
import sys

# Serial port configuration for Raspberry Pi (default UART0 / GPIO 14/15)
SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 9600
TIMEOUT_SEC = 1.0
READ_INTERVAL_SEC = 1.0
MAX_INITIAL_ATTEMPTS = 5
MAX_RETRIES = 3


def open_serial_port(port, baud, timeout):
    """Open the serial port, returning a Serial object or None on failure."""
    try:
        ser = serial.Serial(
            port=port,
            baudrate=baud,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=timeout,
        )
        if not ser.is_open:
            print(f"Error: serial port {port} did not open.")
            return None
        print(f"Serial port {port} opened at {baud} baud.")
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error opening serial port {port}: {e}")
        return None


def read_sensor_data(serial_port):
    """Read a line from the serial port and decode it as ASCII.

    Returns the stripped string, or None on timeout / error.
    """
    try:
        raw = serial_port.readline()
        if not raw:
            return None
        return raw.decode('ascii', errors='replace').strip()
    except serial.SerialException as e:
        print(f"Serial communication error: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error reading from serial port: {e}")
        return None


def process_sensor_data(data):
    """Parse and validate the sensor reading.

    Returns the validated float, or None if the data is invalid.
    """
    if not data:
        return None
    try:
        value = float(data)
    except ValueError:
        print(f"Invalid data received (not numeric): '{data}'")
        return None

    # Validate against documented range
    if not (-200.0 <= value <= 200.0):
        print(f"Value out of range: {value}")
        return None

    return value


def display_sensor_data(value):
    """Print the validated sensor reading to stdout."""
    print(f"Sensor Reading: {value:.2f}")


def main():
    """Main loop: open serial port, read, process, display, repeat."""
    serial_connection = open_serial_port(SERIAL_PORT, BAUD_RATE, TIMEOUT_SEC)
    if serial_connection is None:
        sys.exit(1)

    initial_attempts = 0
    while initial_attempts < MAX_INITIAL_ATTEMPTS:
        data = read_sensor_data(serial_connection)
        if data is not None:
            break
        initial_attempts += 1
        if initial_attempts < MAX_INITIAL_ATTEMPTS:
            print(f"Initial read attempt {initial_attempts}/{MAX_INITIAL_ATTEMPTS} failed.")
            time.sleep(READ_INTERVAL_SEC)

    if initial_attempts >= MAX_INITIAL_ATTEMPTS:
        print("Failed to establish communication with the device after multiple attempts.")
        serial_connection.close()
        print("Serial port closed.")
        sys.exit(1)

    try:
        while True:
            data = read_sensor_data(serial_connection)
            if data is not None:
                processed_value = process_sensor_data(data)
                if processed_value is not None:
                    display_sensor_data(processed_value)
            time.sleep(READ_INTERVAL_SEC)
    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")


if __name__ == "__main__":
    main()

import serial
import signal
import sys

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 9600
READ_TIMEOUT = 2.0
MAX_RETRIES = 3
RETRY_DELAY = 0.5

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def _validate_reading(reading):
    if not isinstance(reading, (int, float)):
        return False
    if isinstance(reading, int) and not (-32768 <= reading <= 32767):
        return False
    if isinstance(reading, float) and not (-32768.0 <= reading <= 32767.0):
        return False
    return True

def read_sensor_data(ser):
    for attempt in range(1, MAX_RETRIES + 1):
        if not _running:
            return None
        try:
            raw = ser.readline()
            if not raw:
                print(f"Warning: no data received (attempt {attempt}/{MAX_RETRIES})")
                if attempt < MAX_RETRIES:
                    time.sleep(RETRY_DELAY)
                    continue
                return None
            data = raw.decode('ascii', errors='replace').strip()
            if not data:
                continue
            try:
                reading = float(data)
            except ValueError:
                print(f"Warning: non-numeric data received: {data!r}")
                if attempt < MAX_RETRIES:
                    time.sleep(RETRY_DELAY)
                    continue
                return None
            if _validate_reading(reading):
                return reading
            print(f"Warning: reading out of range: {reading}")
            if attempt < MAX_RETRIES:
                time.sleep(RETRY_DELAY)
                continue
            return None
        except serial.SerialException as e:
            print(f"Serial communication error: {e}")
            return None
        except Exception as e:
            print(f"Unexpected error reading data: {e}")
            return None
    return None

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    ser = None
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=READ_TIMEOUT)
        print(f"Opened {SERIAL_PORT} at {BAUD_RATE} baud")
        reading = read_sensor_data(ser)
        if reading is not None:
            print(f"Sensor reading: {reading}")
        else:
            print("Failed to obtain valid sensor reading.")
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        sys.exit(1)
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == "__main__":
    import time
    main()

