def write_reg(bus, addr, reg, value):
    bus.write_byte_data(addr, reg, value)


def read_reg(bus, addr, reg):
    return bus.read_byte_data(addr, reg)


def read_channel(bus, addr, channel):
    base = PCA9685_LED0_ON_L + 4 * channel
    lo = read_reg(bus, addr, base)
    hi = read_reg(bus, addr, base + 1)
    return (hi << 8) | lo


def main():
    global bus
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        bus = SMBus(1)
    except OSError as e:
        print(f"Error: cannot open I2C bus 1: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        try:
            mode1 = read_reg(bus, PCA9685_ADDRESS, PCA9685_MODE1)
        except OSError as e:
            print(f"Error: no PCA9685 found at 0x{PCA9685_ADDRESS:02X}: {e}", file=sys.stderr)
            sys.exit(1)

        if (mode1 & MODE1_SLEEP) != 0:
            write_reg(bus, PCA9685_ADDRESS, PCA9685_MODE1, mode1 | MODE1_RESTART)
            time.sleep(0.005)
            mode1 = read_reg(bus, PCA9685_ADDRESS, PCA9685_MODE1)

        prescale = 0x1F & ((25000000 + 1000000) / 4096 / 50 - 1)
        write_reg(bus, PCA9685_ADDRESS, PCA9685_PRESCALE, prescale)
        write_reg(bus, PCA9685_ADDRESS, PCA9685_MODE1, mode1 | MODE1_SLEEP | MODE1_RESTART)
        time.sleep(0.005)
        write_reg(bus, PCA9685_ADDRESS, PCA9685_MODE1, mode1 & ~MODE1_SLEEP)

        while running:
            try:
                value = read_channel(bus, PCA9685_ADDRESS, 0)
            except OSError as e:
                print(f"Error: I2C read failed: {e}", file=sys.stderr)
                break
            if value < 0 or value > 4095:
                print("Error: reading out of range", file=sys.stderr)
                break
            print(value)
            time.sleep(0.15)
    finally:
        if bus is not None:
            try:
                write_reg(bus, PCA9685_ADDRESS, PCA9685_MODE1, read_reg(bus, PCA9685_ADDRESS, PCA9685_MODE1) | MODE1_SLEEP)
            except OSError:
                pass
            bus.close()


if __name__ == "__main__":
    main()

