import serial
import time
import sys

SERIAL_PORT = '/dev/serial0'  # Raspberry Pi primary UART (BCM 14/15)
BAUD_RATE = 9600
READ_TIMEOUT = 1.0
INTERVAL = 0.05


def main() -> int:
    # Open the serial port; exit non-zero if the device is absent.
    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            timeout=READ_TIMEOUT,
            write_timeout=READ_TIMEOUT,
        )
    except serial.SerialException as exc:
        print(f"Error: cannot open {SERIAL_PORT}: {exc}", file=sys.stderr)
        return 1

    print(f"Listening on {SERIAL_PORT} @ {BAUD_RATE} baud (Ctrl+C to stop).")

    try:
        while True:
            try:
                # readline() returns b'' on timeout; treat as no data.
                raw = ser.readline()
                if raw:
                    print(raw.decode('utf-8', errors='replace').strip())
            except serial.SerialException as exc:
                # Device disappeared or write error — report and abort.
                print(f"Serial error: {exc}", file=sys.stderr)
                return 1

            time.sleep(INTERVAL)
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    finally:
        # Release the hardware on every exit path.
        try:
            ser.close()
        except Exception:
            pass
    return 0


if __name__ == "__main__":
    sys.exit(main())

