                except GPIOZeroError as exc:
                    print(f"Warning: failed to drive GPIO {dev.pin.number}: {exc}", file=sys.stderr)
                time.sleep(POLL_INTERVAL)

    except GPIOZeroWarning:
        pass
    finally:
        for dev in devices:
            try:
                dev.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")

