import time
import signal
import sys
import board
import adafruit_dht

# DHT22 pins (BCM numbering) as per the prompt
DHT_PINS = {
    4, 17, 18, 22, 23, 27
}

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False


def main():
    global _running

    # Register signal handlers for graceful termination
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Initialize DHT22 sensors on all specified pins
    sensors = {}
    for pin in DHT_PINS:
        try:
            # Map BCM pin number to board pin name (e.g., D4 -> board.D4)
            pin_name = f"D{pin}"
            sensors[pin] = adafruit_dht.DHT22(getattr(board, pin_name))
        except Exception as e:
            print(f"Warning: Failed to initialize DHT22 on GPIO {pin}: {e}", file=sys.stderr)

    if not sensors:
        print("Error: No DHT22 sensors initialized. Exiting.", file=sys.stderr)
        sys.exit(1)

    try:
        # Run 3 cycles, one every 5 seconds
        for cycle in range(3):
            if not _running:
                break

            print(f"\n--- Cycle {cycle + 1} ---")

            for pin, sensor in sensors.items():
                try:
                    temperature = sensor.temperature
                    humidity = sensor.humidity

                    if temperature is not None and humidity is not None:
                        print(f"GPIO {pin}: Temperature = {temperature:.1f}°C, Humidity = {humidity:.1f}%")
                    else:
                        print(f"GPIO {pin}: Failed to read data (None returned).")
                except RuntimeError as e:
                    # DHT22 often throws transient read errors; log and continue
                    print(f"GPIO {pin}: Read error: {e}")
                except Exception as e:
                    print(f"GPIO {pin}: Unexpected error: {e}")

            if cycle < 2:
                # Sleep in small increments to allow signal handler to interrupt promptly
                slept = 0.0
                while slept < 5.0 and _running:
                    time.sleep(0.1)
                    slept += 0.1

    finally:
        # Release all sensor resources on exit
        for sensor in sensors.values():
            try:
                sensor.exit()
            except Exception:
                pass
        print("\nResources released. Exiting.")


if __name__ == "__main__":
    main()

