import sys
import time

import adafruit_dht
from board import D4, D17, D27

# Global flag for graceful shutdown
_running = True


def _handle_signal(signum, frame):
    """Signal handler for graceful shutdown."""
    global _running
    _running = False


def main():
    """Continuously read and print DHT22 sensor data on GPIO 4, 17, 27."""
    global _running

    # Register signal handlers for clean exit
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # Initialize DHT22 sensors on the specified GPIO pins
    sensors = []
    pins = [D4, D17, D27]
    for pin in pins:
        try:
            sensor = adafruit_dht.DHT22(pin, use_pulseio=False)
            sensors.append(sensor)
        except Exception as e:
            print(f"Warning: Failed to initialize DHT22 on pin {pin}: {e}", file=sys.stderr)
            continue

    if not sensors:
        print("Error: No DHT22 sensors could be initialized.", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            for sensor in sensors:
                try:
                    temperature = sensor.temperature
                    humidity = sensor.humidity
                    if temperature is not None and humidity is not None:
                        print(f"DHT22: Temperature = {temperature:.1f} C, Humidity = {humidity:.1f} %")
                    else:
                        print("DHT22: Failed to read data (None returned).", file=sys.stderr)
                except RuntimeError as e:
                    # DHT22 often throws transient read errors; log and continue
                    print(f"DHT22: Read error: {e}", file=sys.stderr)
                except Exception as e:
                    print(f"DHT22: Unexpected error: {e}", file=sys.stderr)

            time.sleep(1)

    finally:
        # Clean resource release on all exit paths
        for sensor in sensors:
            try:
                sensor.exit()
            except Exception:
                pass
        print("Program terminated.")


