import signal
import sys
import time

try:
    from smbus2 import SMBus
except ImportError:
    print("Error: smbus2 not installed. Install with: pip install smbus2", file=sys.stderr)
    sys.exit(1)

MPU6050_ADDR = 0x68
PWR_MGMT_1 = 0x6B
WHO_AM_I = 0x75
EXPECTED_WHO_AM_I = 0x68

bus = None
running = True


def handle_signal(signum, frame):
    global running
    running = False


def read_mpu6050(bus):
    """Read a single 16-bit signed value from the MPU6050."""
    try:
        data = bus.read_i2c_block_data(MPU6050_ADDR, 0x3B, 2)
        raw = (data[0] << 8) | data[1]
        if raw >= 0x8000:
            raw -= 0x10000
        return raw
    except OSError as e:
        raise RuntimeError(f"I2C read failed: {e}")


def main():
    global bus

    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        bus = SMBus(1)
    except OSError as e:
        print(f"Error: cannot open I2C bus 1: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        # Wake up the MPU6050 (clear sleep bit)
        try:
            bus.write_byte_data(MPU6050_ADDR, PWR_MGMT_1, 0x00)
        except OSError as e:
            print(f"Error: cannot wake MPU6050: {e}", file=sys.stderr)
            sys.exit(1)

        # Verify device identity
        try:
            who = bus.read_byte_data(MPU6050_ADDR, WHO_AM_I)
        except OSError as e:
            print(f"Error: MPU6050 not responding at 0x{MPU6050_ADDR:02X}: {e}", file=sys.stderr)
            sys.exit(1)

        if who != EXPECTED_WHO_AM_I:
            print(f"Error: Unexpected WHO_AM_I value 0x{who:02X}, expected 0x{EXPECTED_WHO_AM_I:02X}", file=sys.stderr)
            sys.exit(1)

        print("MPU6050 detected and initialized.")

        for i in range(5):
            if not running:
                print("\nInterrupted by signal, exiting early.")
                break

            try:
                accel_x = read_mpu6050(bus)
                accel_y = read_mpu6050(bus)
                accel_z = read_mpu6050(bus)
                print(f"Reading {i + 1}/5 - Accel X: {accel_x}, Accel Y: {accel_y}, Accel Z: {accel_z}")
            except RuntimeError as e:
                print(f"Error reading MPU6050: {e}", file=sys.stderr)
                break

            time.sleep(0.1)

    finally:
        if bus is not None:
            try:
                bus.close()
            except OSError:
                pass
        print("I2C bus closed.")


if __name__ == "__main__":
    main()

