import time
import signal
import sys
import board
import adafruit_dht

# DHT11 connected to GPIO 17 (BCM) = board.D17
DHT_PIN = board.D17
MAX_CYCLES = 5
DELAY_SECONDS = 0.5

# Global so the signal handler can release the device
_sensor = None
_running = True


def _cleanup():
    """Release the DHT device if it was initialised."""
    global _sensor
    if _sensor is not None:
        try:
            _sensor.exit()
        except Exception:
            pass
        _sensor = None


def _handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def main():
    global _sensor

    # Register signal handlers for clean exit
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # Initialise the DHT11 device
    try:
        _sensor = adafruit_dht.DHT11(DHT_PIN, use_pulseio=False)
    except Exception as exc:
        print(f"Error: failed to initialise DHT11 on GPIO 17: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    try:
        for cycle in range(1, MAX_CYCLES + 1):
            if not _running:
                break

            try:
                temperature = _sensor.temperature
                humidity = _sensor.humidity

                if temperature is None or humidity is None:
                    print(f"Cycle {cycle}: sensor returned None (check wiring/pin).", file=sys.stderr)
                else:
                    print(f"Cycle {cycle}: Temperature = {temperature:.1f} C, Humidity = {humidity:.1f} %")
            except RuntimeError as exc:
                # DHT11 checksum / timing glitches are common; report and continue
                print(f"Cycle {cycle}: read error ({exc}).", file=sys.stderr)
            except Exception as exc:
                # Unexpected error (e.g. device disconnected)
                print(f"Cycle {cycle}: unexpected error ({exc}).", file=sys.stderr)

            if cycle < MAX_CYCLES and _running:
                time.sleep(DELAY_SECONDS)

    finally:
        _cleanup()

    if not _running:
        sys.exit(130)  # 128 + SIGINT
    sys.exit(0)


if __name__ == "__main__":
    main()

