import serial
import time
import sys

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 115200
READ_TIMEOUT = 1.0
INTERVAL = 0.1


def is_valid_reading(reading: str) -> bool:
    """Return True only when the reading is a non-empty, non-whitespace string."""
    return isinstance(reading, str) and reading.strip() != ''


def read_sensor_data(ser: serial.Serial) -> str | None:
    """Read one line from the serial port and validate it.

    Returns the validated string, or None if the line is empty or invalid.
    """
    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        print(f"Serial read error: {exc}", file=sys.stderr)
        return None

    if not raw:
        return None

    try:
        line = raw.decode('utf-8', errors='replace').strip()
    except Exception as exc:
        print(f"Decode error: {exc}", file=sys.stderr)
        return None

    return line if is_valid_reading(line) else None


def main() -> int:
    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            timeout=READ_TIMEOUT,
            write_timeout=READ_TIMEOUT,
        )
    except serial.SerialException as exc:
        print(f"Failed to open serial port {SERIAL_PORT}: {exc}", file=sys.stderr)
        return 1

    print(f"Listening on {SERIAL_PORT} @ {BAUD_RATE} baud (Ctrl+C to stop)")

    try:
        while True:
            reading = read_sensor_data(ser)
            if reading is not None:
                print(f"Sensor Reading: {reading}")
            time.sleep(INTERVAL)
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    finally:
        if ser.is_open:
            ser.close()
            print("Serial port closed.")
    return 0


if __name__ == "__main__":
    sys.exit(main())

