import signal
import sys
import time

from smbus2 import SMBus

# INA219 constants
INA219_ADDRESS = 0x40
INA219_REG_CONFIG = 0x00
INA219_REG_SHUNT_VOLTAGE = 0x01
INA219_REG_BUS_VOLTAGE = 0x02
INA219_REG_POWER = 0x03
INA219_REG_CURRENT = 0x04
INA219_REG_CALIBRATION = 0x05

# Config register bits
INA219_CONFIG_RESET = 0x8000
INA219_CONFIG_SVOLTAGE = 0x0003
INA219_CONFIG_BVOLTAGE = 0x0000
INA219_CONFIG_MODE = 0x0000  # Continuous conversion mode

# Calibration: Rshunt = 0.1 ohm, max current 3.2 A -> R = 0.01 ohm
# I_LSB = 0.1 mA, 32767 LSB -> Calibration = 0.04096 / (I_LSB * R)
INA219_CALIBRATION_VALUE = 0x4000  # 16384 for Rshunt=0.1 ohm, I_LSB=0.1 mA

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def _write_reg(bus, address, register, value):
    bus.write_word_data(address, register, value)


def _read_reg(bus, address, register):
    return bus.read_word_data(address, register)


def _swap_bytes(value):
    return ((value & 0xFF00) >> 8) | ((value & 0x00FF) << 8)


def _validate_reading(value):
    """Reject readings that overflow the 16-bit signed range."""
    if not (-32768 <= value <= 32767):
        return False
    return True


def _read_ina219(bus, address):
    """Read and validate a 16-bit signed value from the INA219."""
    raw = _read_reg(bus, address, register)
    swapped = _swap_bytes(raw)
    if not _validate_reading(swapped):
        return None
    return swapped


def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    bus = None
    try:
        bus = SMBus(1)
    except OSError as e:
        print(f"Error: cannot open I2C bus 1: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        # Probe the device
        try:
            _read_reg(bus, INA219_ADDRESS, INA219_REG_CONFIG)
        except OSError as e:
            print(f"Error: INA219 not found at address 0x{INA219_ADDRESS:02X}: {e}", file=sys.stderr)
            sys.exit(1)

        # Reset and configure the device
        try:
            _write_reg(bus, INA219_ADDRESS, INA219_REG_CONFIG, INA219_CONFIG_RESET)
            time.sleep(0.005)  # Wait for reset
            _write_reg(bus, INA219_ADDRESS, INA219_REG_CONFIG, INA219_CONFIG_SVOLTAGE | INA219_CONFIG_BVOLTAGE | INA219_CONFIG_MODE)
            _write_reg(bus, INA219_ADDRESS, INA219_REG_CALIBRATION, INA219_CALIBRATION_VALUE)
        except OSError as e:
            print(f"Error: failed to configure INA219: {e}", file=sys.stderr)
            sys.exit(1)

        print("INA219 initialized. Reading every 2 seconds (Ctrl+C to stop).")

        while _running:
            try:
                shunt = _read_ina219(bus, INA219_ADDRESS)
                if shunt is None:
                    print("Warning: invalid reading, skipping.", file=sys.stderr)
                else:
                    print(f"Shunt Voltage: {shunt} uV")
            except OSError as e:
                print(f"Warning: I2C read error: {e}", file=sys.stderr)

            time.sleep(2)

    finally:
        if bus is not None:
            try:
                bus.close()
            except OSError:
                pass
        print("\nExiting cleanly.")


if __name__ == "__main__":
    main()

