import time
import signal
import sys
from gpiozero import DistanceSensor

# HC-SR04 ultrasonic distance sensor on a Raspberry Pi
#  VCC  -> 5V,  GND -> GND,  TRIG -> GPIO17,  ECHO -> GPIO18
TRIGGER_PIN = 17
ECHO_PIN = 18
MAX_DISTANCE = 4.0  # meters (HC-SR04 practical range)
NUM_READINGS = 10
DELAY_SECONDS = 0.1

_running = True


def _handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def read_distance(sensor):
    """
    Read distance from the HC-SR04.

    Returns:
        float: Distance in meters, or None if the reading is invalid.
    """
    try:
        distance = sensor.distance
        if distance is None or distance < 0 or distance > MAX_DISTANCE:
            return None
        return distance
    except Exception as exc:
        print(f"Error reading distance: {exc}", file=sys.stderr)
        return None


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        sensor = DistanceSensor(
            echo=ECHO_PIN,
            trigger=TRIGGER_PIN,
            max_distance=MAX_DISTANCE,
        )
    except Exception as exc:
        print(f"Failed to initialize HC-SR04: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        for i in range(NUM_READINGS):
            if not _running:
                print("Interrupted by user; stopping early.")
                break

            distance = read_distance(sensor)
            if distance is not None:
                print(f"Reading {i + 1}/{NUM_READINGS}: {distance:.2f} meters")
            else:
                print(f"Reading {i + 1}/{NUM_READINGS}: invalid reading", file=sys.stderr)

            if i < NUM_READINGS - 1:
                time.sleep(DELAY_SECONDS)
    finally:
        try:
            sensor.close()
        except Exception:
            pass
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

