import signal
import sys
import time

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

PWM_PINS = [5, 6, 13, 17, 18, 22, 23, 24, 27]
PWM_FREQUENCY = 1000  # Hz
POLL_INTERVAL = 1.0   # seconds

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _report_state(devices):
    """Print the current duty cycle of every PWM device."""
    for pin, dev in devices.items():
        try:
            value = dev.value
        except DeviceClosed:
            print(f"GPIO {pin}: device closed", file=sys.stderr)
            continue
        print(f"GPIO {pin}: duty cycle {value:.3f}")


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = {}
    try:
        for pin in PWM_PINS:
            try:
                dev = PWMOutputDevice(pin, frequency=PWM_FREQUENCY, initial_value=0.0)
                devices[pin] = dev
            except GPIOZeroError as exc:
                print(f"GPIO {pin}: failed to initialize PWM output: {exc}", file=sys.stderr)
                for d in devices.values():
                    d.close()
                sys.exit(1)
    except GPIOZeroError as exc:
        print(f"Failed to initialize any PWM pins: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            _report_state(devices)
            time.sleep(POLL_INTERVAL)
    except Exception as exc:
        print(f"Runtime error: {exc}", file=sys.stderr)
        sys.exit(1)
    finally:
        for dev in devices.values():
            try:
                dev.value = 0.0
            except DeviceClosed:
                pass
            try:
                dev.close()
            except Exception:
                pass
        print("PWM devices released.")


if __name__ == "__main__":
    main()

