import serial
import time
import sys

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 115200
READ_TIMEOUT = 1.0
INTERVAL = 0.1


def main() -> int:
    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            timeout=READ_TIMEOUT,
            write_timeout=READ_TIMEOUT,
        )
    except serial.SerialException as exc:
        print(f"Error: cannot open serial port {SERIAL_PORT}: {exc}", file=sys.stderr)
        return 1

    try:
        while True:
            try:
                raw = ser.readline()
            except serial.SerialException as exc:
                print(f"Error: serial read failed: {exc}", file=sys.stderr)
                return 1

            if raw:
                print(raw.decode('utf-8', errors='replace').strip())
            else:
                # Timed out waiting for data; device may be absent or unresponsive.
                print("Warning: no data received within timeout — device may be absent or unresponsive.",
                      file=sys.stderr)
                break

            time.sleep(INTERVAL)
    finally:
        try:
            ser.close()
        except Exception:
            pass

    return 0


if __name__ == '__main__':
    sys.exit(main())

