import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 115200
READ_TIMEOUT = 2.0
NUM_READINGS = 3
INTERVAL = 2.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def read_sensor_data(ser, num_readings):
    readings_taken = 0
    while readings_taken < num_readings and _running:
        try:
            data = ser.readline()
            if data:
                print(f'Sensor Reading: {data.decode("utf-8", errors="replace").strip()}')
                readings_taken += 1
            else:
                print('Warning: no data received (timeout).')
        except serial.SerialException as e:
            print(f'Serial communication error: {e}')
            return readings_taken
        except OSError as e:
            print(f'I/O error: {e}')
            return readings_taken
        if readings_taken < num_readings and _running:
            time.sleep(INTERVAL)
    return readings_taken

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            timeout=READ_TIMEOUT,
            write_timeout=READ_TIMEOUT
        )
    except serial.SerialException as e:
        print(f'Error opening serial port {SERIAL_PORT}: {e}')
        sys.exit(1)
    except OSError as e:
        print(f'OS error opening {SERIAL_PORT}: {e}')
        sys.exit(1)

    try:
        readings = read_sensor_data(ser, NUM_READINGS)
        if readings == 0:
            print('No readings were successfully received.')
        else:
            print(f'Data exchange complete. Readings taken: {readings}')
    finally:
        try:
            ser.close()
            print('Serial port closed.')
        except Exception:
            pass

if __name__ == '__main__':
    main()

import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

TSL2591_ADDR = 0x29
TSL2591_CMD_REGISTER = 0x80
TSL2591_REGISTER_CONTROL = 0x00
TSL2591_REGISTER_CHAN0_LOW = 0x14
TSL2591_REGISTER_CHAN1_LOW = 0x16
TSL2591_REGISTER_ID = 0x12
TSL2591_ID = 0x50

running = True
bus = None


def _signal_handler(signum, frame):
    global running
    running = False


def _read_word(bus, reg):
    write_msg = i2c_msg.write(TSL2591_ADDR, [TSL2591_CMD_REGISTER | reg])
    read_msg = i2c_msg.read(TSL2591_ADDR, 2)
    bus.i2c_rdwr(write_msg, read_msg)
    return (read_msg.buf[0] << 8) | read_msg.buf[1]


def _read_channel(bus, ch):
    if ch == 0:
        lo = _read_word(bus, TSL2591_REGISTER_CHAN0_LOW)
    else:
        lo = _read_word(bus, TSL2591_REGISTER_CHAN1_LOW)
    hi = _read_word(bus, TSL2591_REGISTER_CHAN0_LOW + 2)
    return (hi << 16) | lo


def _read_adc(bus):
    ch0 = _read_channel(bus, 0)
    ch1 = _read_channel(bus, 1)
    if ch0 == 0 and ch1 == 0:
        return None
    return ch0, ch1


def _read_light_level(bus):
    ch0, ch1 = _read_adc(bus)
    if ch0 is None:
        return None
    return (ch0 + ch1) / 2.0


def _init_device(bus):
    ident = _read_word(bus, TSL2591_REGISTER_ID)
    if ident != TSL2591_ID:
        return False
    ctrl = _read_word(bus, TSL2591_REGISTER_CONTROL)
    if ctrl & 0x01:
        return True
    ctrl |= 0x01
    _write_word(bus, TSL2591_REGISTER_CONTROL, ctrl)
    return True


def _write_word(bus, reg, value):
    write_msg = i2c_msg.write(TSL2591_ADDR, [TSL2591_CMD_REGISTER | reg, value & 0xFF])
    bus.i2c_rdwr(write_msg)


def main():
    global bus
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        bus = SMBus(1)
    except OSError as exc:
        print(f"Error: cannot open I2C bus 1: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        if not _init_device(bus):
            print("Error: TSL2591 not detected at address 0x29.", file=sys.stderr)
            sys.exit(1)

        for i in range(3):
            if not running:
                break
            try:
                level = _read_light_level(bus)
            except OSError as exc:
                print(f"Error: I2C read failed on sample {i + 1}: {exc}", file=sys.stderr)
                sys.exit(1)
            if level is None:
                print(f"Error: invalid reading on sample {i + 1}.", file=sys.stderr)
                sys.exit(1)
            print(f"Light level: {level:.2f}")
            if i < 2 and running:
                time.sleep(10)
    finally:
        if bus is not None:
            try:
                bus.close()
            except OSError:
                pass


if __name__ == "__main__":
    main()

