import signal
import sys
import time

import adafruit_dht
from board import D4

# Global so the signal handler can clean up
_sensor = None
_running = True


def _cleanup():
    """Release the DHT22 hardware resource."""
    global _sensor
    if _sensor is not None:
        try:
            _sensor.exit()
        except Exception:
            pass
        _sensor = None


def _handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def main():
    global _sensor

    # Register signal handlers for clean exit
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # Initialize the DHT22 on GPIO 4 (BCM) via the board module
    try:
        _sensor = adafruit_dht.DHT22(D4, use_pulseio=False)
    except Exception as exc:
        print(f"Failed to initialize DHT22 on GPIO 4: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    try:
        for cycle in range(3):
            if not _running:
                break

            try:
                temperature = _sensor.temperature
                humidity = _sensor.humidity

                if temperature is None or humidity is None:
                    print(f"Cycle {cycle + 1}: sensor returned None (check wiring)")
                else:
                    print(f"Cycle {cycle + 1}: Temperature = {temperature:.1f} C, Humidity = {humidity:.1f} %")
            except RuntimeError as exc:
                # DHT22 checksum / timing errors are common; report and continue
                print(f"Cycle {cycle + 1}: read error ({exc})")
            except Exception as exc:
                print(f"Cycle {cycle + 1}: unexpected error ({exc})")

            time.sleep(2.0)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()
